(()=>{const C=JZM_CAD_PILOT,D=JZM_MAP_DATA,P=JZM_LAYER_WORKSPACE.provenance,L=D.layers.find(l=>l.id==='study_boundary');
 const prior={...L,id:'study_boundary_parcel',label:'Řešené území · dřívější parcelní interpretace',color:'#e58b17'};D.layers.push(prior);P.study_boundary_parcel={...P.study_boundary,short:'S004 × ČÚZK · předchozí pracovní výběr parcel'};
 Object.assign(L,{label:'Řešené území · původní DWG S005',source_id:'S005',page:null,color:'#0874bc',feature_count:1,geojson:C.boundary,description:'S005 · CAD hranice · bez přichycení ke katastru'});
 P.study_boundary={short:L.description,steps:['Lokální převod ODA 27.10 do DXF 2013; bez automatické opravy.','11 návazných čar vrstvy a_hranice_řešeného_území složeno do jednoho polygonu.','INSUNITS=4: mm → m (0,001); ověřeno proti parcelní kresbě ČÚZK. Následně EPSG:5514 → WGS84. Bez posunu či přichycení.','GIS plocha přibližně 20,95 ha. S006 obsahuje shodnou hranici.'],limits:'99,99 % kontrolních vzorků parcelní kresby CAD leží do 5 cm od snapshotu ČÚZK. Jde o digitální shodu, nikoli geodetickou přesnost. Samotná řešená hranice místy protíná parcely; největší zjištěná vzdálenost vzorku od nejbližší parcelní hrany je 5,93 m. Starší interpretace zůstává k porovnání.',links:[{label:'GeoJSON CAD hranice',path:'cad_data/261117_v01/gis/S005_boundary.geojson'},{label:'Původní DWG S005',path:'sources/S005.dwg'},{label:'Převedený DXF S005',path:'cad_data/261117_v01/S005/dxf/S005.dxf'},{label:'Srovnání hranic',path:'cad_data/261117_v01/boundary-comparison.svg'},{label:'Měření shody s katastrem',path:'cad_data/261117_v01/alignment-comparison.json'}]};
 for(const l of C.layers){if(!l.feature_count)continue;D.layers.push(l);P[l.id]={short:l.description,steps:['Původní CAD vrstva: '+l.cad_layer+'.','Lokální ODA 27.10 → DXF; ezdxf 1.4.5. mm → m → EPSG:5514 → WGS84.','Výběr celých prvků protínajících řešené území nebo jeho okolí do 120 m; bez ořezu či přichycení.','Čáry zachovány; křivky aproximovány s tolerancí 0,02 m. Šrafy převedeny na plochy s vnitřními otvory.'],limits:'Význam podle názvu vrstvy je pracovní interpretace. DWG neobsahuje textovou legendu. Stav sítí, zkratky RZ/N a právní platnost pásem nejsou potvrzené. Počet označuje CAD entity, nikoli počet fyzických zařízení. Původní úplný obsah zůstává v DXF.',links:[{label:'GeoJSON této vrstvy',path:l.geojson_path},{label:'Původní DWG S006',path:'sources/S006.dwg'},{label:'Převedený DXF S006',path:'cad_data/261117_v01/S006/dxf/S006.dxf'},{label:'Inventář CAD',path:'cad_data/261117_v01/cad-layer-catalog.json'},{label:'Pokrytí a vynechané prvky',path:'cad_data/261117_v01/extraction-coverage.json'}]};}
 P.parcel_ownership.limits+=' Nová CAD hranice nemění historické přiřazení vlastníků ani výběr těchto 176 parcel. Rozsah CAD se eviduje zvlášť.';
 for(const d of D.coverage){if(['S005','S006'].includes(d.source_id)){d.status='cad_exported';d.note=d.source_id==='S005'?'CAD hranice převedena z 11 čar; ostatní obsah evidován v inventáři.':'6 924 prvků v území a okolí do 120 m; zbývající obsah zachován v DXF.';}}
})();
